select
    gateway_id
from  b_marketing_line_base_info_normal
where
    line_supplier_id = #{lineSupplierId}
    and project_name=#{projectName}
    and caller =#{caller}
    and ope_status in (0,2)
    and is_delete = 0

mapper.update:
update
    b_marketing_line_base_info_normal  set ope_status = #{opeStatus},ope_time = now()
where gateway_id in (

        #{gateway_id}

) and ope_status in (0,2)

