SELECT * FROM ( SELECT id, gateway_id, caller, line_supplier_id, project_name, outbound_number, create_time, update_time, ope_status, ope_time, is_delete, -- 分区按gateway_id，排序规则：优先ope_status in (0,2)的记录 ROW_NUMBER() OVER ( PARTITION BY gateway_id ORDER BY CASE WHEN ope_status IN (0, 2) THEN 0 ELSE 1 END, create_time DESC ) as rn FROM b_marketing_line_base_info_normal WHERE gateway_id IN (
#{gateway_id}
) AND is_delete = 0 ) t WHERE rn = 1
